  content,
  params,
  previousRun,
  extraToolResults,
  signal,
  drainSteeringMessages,
  costMode,
  extraCodebuffMetadata,
  onStateSnapshot,
  onUsage,
  onUsageIncomplete,
  onCompaction,
  onCompactionStart,
  onCompactionEnd,
  terminalShell,
  projectKey,
  traceSessionId: traceSessionIdOption,
