                    toolCall.function?.name != null &&
                    toolCall.function?.arguments != null
                  ) {
                    // send delta if the argument text has already started:
                    if (toolCall.function.arguments.length > 0) {
                      controller.enqueue({
                        type: 'tool-input-delta',
                        id: toolCall.id,
                        delta: toolCall.function.arguments,
                      })
                    }

                    // check if tool call is complete
                    // (some providers send the full tool call in one chunk):
                    if (isParsableJson(toolCall.function.arguments)) {
                      controller.enqueue({
                        type: 'tool-input-end',
                        id: toolCall.id,
                      })

                      controller.enqueue({
                        type: 'tool-call',
                        toolCallId: toolCall.id ?? generateId(),
                        toolName: toolCall.function.name,
                        input: toolCall.function.arguments,
                      })
                      toolCall.hasFinished = true
                    }
                  }

                  continue
                }

                // existing tool call, merge if not finished
                const toolCall = toolCalls[index]

                if (toolCall.hasFinished) {
                  continue
                }

                if (toolCallDelta.function?.arguments != null) {
                  toolCall.function!.arguments +=
                    toolCallDelta.function?.arguments ?? ''
                }

                // send delta
                controller.enqueue({
                  type: 'tool-input-delta',
                  id: toolCall.id,
                  delta: toolCallDelta.function.arguments ?? '',
                })

                // check if tool call is complete
                if (
                  toolCall.function?.name != null &&
                  toolCall.function?.arguments != null &&
                  isParsableJson(toolCall.function.arguments)
                ) {
                  controller.enqueue({
                    type: 'tool-input-end',
                    id: toolCall.id,
                  })

                  controller.enqueue({
                    type: 'tool-call',
                    toolCallId: toolCall.id ?? generateId(),
                    toolName: toolCall.function.name,
                    input: toolCall.function.arguments,
                  })
                  toolCall.hasFinished = true
                }
              }
            }
          },

          flush(controller) {
            // Signature-only reasoning (e.g. fully redacted thinking) arrives
            // as details with no reasoning text; open the part so the details
            // still get a reasoning-end to ride on.
            if (!isActiveReasoning && reasoningDetails.length > 0) {
              controller.enqueue({ type: 'reasoning-start', id: 'reasoning-0' })
              isActiveReasoning = true
            }
            if (isActiveReasoning) {
              controller.enqueue({
                type: 'reasoning-end',
                id: 'reasoning-0',
                ...(reasoningDetails.length > 0
                  ? {
                      providerMetadata: {
                        [providerOptionsName]: {
                          reasoning_details: reasoningDetails,
                          model: modelId,
                        },
                      } as SharedV2ProviderMetadata,
                    }
                  : {}),
              })
            }

            if (isActiveText) {
              controller.enqueue({ type: 'text-end', id: 'txt-0' })
            }

            // go through all tool calls and send the ones that are not finished
            for (const toolCall of toolCalls.filter(
              (toolCall) => !toolCall.hasFinished,
            )) {
              controller.enqueue({
                type: 'tool-input-end',
                id: toolCall.id,
              })

              controller.enqueue({
                type: 'tool-call',
                toolCallId: toolCall.id ?? generateId(),
                toolName: toolCall.function.name,
                input: toolCall.function.arguments,
              })
            }

            const providerMetadata: SharedV2ProviderMetadata = {
              [providerOptionsName]: {},
              ...metadataExtractor?.buildMetadata(),
            }
            if (
              usage.completionTokensDetails.acceptedPredictionTokens != null
            ) {
              providerMetadata[providerOptionsName].acceptedPredictionTokens =
                usage.completionTokensDetails.acceptedPredictionTokens
            }
            if (
              usage.completionTokensDetails.rejectedPredictionTokens != null
            ) {
              providerMetadata[providerOptionsName].rejectedPredictionTokens =
                usage.completionTokensDetails.rejectedPredictionTokens
            }

            controller.enqueue({
              type: 'finish',
              finishReason,
              usage: {
                inputTokens: usage.promptTokens ?? undefined,
                outputTokens: usage.completionTokens ?? undefined,
                totalTokens: usage.totalTokens ?? undefined,
                reasoningTokens:
                  usage.completionTokensDetails.reasoningTokens ?? undefined,
                cachedInputTokens:
                  usage.promptTokensDetails.cachedTokens ?? undefined,
              },
              providerMetadata,
            })
          },
        }),
      ),
      request: { body },
      response: { headers: responseHeaders },
    }
  }
}

/**
 * The slot of a streamed tool-call delta that carries no `index`. OpenAI
 * always sends one, but several OpenAI-compatible servers and proxies do not
 * (seen with local routers in front of other providers), and a chunk that
 * failed the schema dropped the call: the turn ended with "Writing the
 * file." and no write. Without an index:
 * - an `id` names its call: an existing one continues, a new one opens a slot;
 * - a delta with no `id` continues the call still being streamed, unless it
 *   names a different function (then it is a new call);
 * - anything else opens a new slot.
 */
export function inferToolCallIndex(
  toolCalls: ReadonlyArray<
    | { id: string; function: { name: string }; hasFinished: boolean }
    | undefined
  >,
  delta: { id?: string | null; function: { name?: string | null } },
): number {
  if (delta.id != null) {
    const existing = toolCalls.findIndex((call) => call?.id === delta.id)
    return existing === -1 ? toolCalls.length : existing
  }
  const lastIndex = toolCalls.length - 1
  const last = toolCalls[lastIndex]
  if (
    last &&
    !last.hasFinished &&
    (delta.function.name == null || delta.function.name === last.function.name)
  )
    return lastIndex
  return delta.function.name == null && last ? lastIndex : toolCalls.length
}

