 */
export function enterByokSetup(): void {
  useChatStore
    .getState()
    .setMessages((messages) => [
      ...messages,
      getSystemMessage(
        [
          'Set up your own provider key (BYOK). BYOK runs never spend Freebucks.',
          '',
