+const UTM_CAMPAIGN_MAX_CHARS = 64
+
+function hasUtmParams(url: URL): boolean {
+  for (const key of url.searchParams.keys()) {
+    if (key.toLowerCase().startsWith('utm_')) return true
+  }
+  return false
