import { getCliEnv } from './env'

export type SecretStore = {
  get(): Promise<string | null>
  set(value: string): Promise<void>
  delete(): Promise<void>
}

const KEYCHAIN_TIMEOUT_MS = 2_000

function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('keychain timed out')), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (error) => {
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}

type BunSecrets = {
  get(options: { service: string; name: string }): Promise<string | null>
  set(options: { service: string; name: string; value: string }): Promise<void>
  delete(options: { service: string; name: string }): Promise<boolean>
}

/** The `Bun.secrets` store for one credentials file, or null when this
 *  runtime has none (Node, an old Bun). */
export function bunSecretStore(
  service: string,
  name: string,
): SecretStore | null {
  const secrets = (globalThis as { Bun?: { secrets?: BunSecrets } }).Bun
    ?.secrets
  if (!secrets) return null
  return {
    get: () => withTimeout(secrets.get({ service, name }), KEYCHAIN_TIMEOUT_MS),
    set: (value) =>
      withTimeout(secrets.set({ service, name, value }), KEYCHAIN_TIMEOUT_MS),
    delete: async () => {
      await withTimeout(secrets.delete({ service, name }), KEYCHAIN_TIMEOUT_MS)
    },
  }
}

