    if (!stderrTail || (code === 0 && !signal)) return false
    const text = sanitizeForReplay(stderrTail)
    return (
      BUN_NO_AVX2_FEATURE.test(text) || BUN_ILLEGAL_INSTRUCTION_PANIC.test(text)
    )
  }

