      // usually exits with plain code 3, and the reason is only in its stderr
      // (see stderrReportsMissingCpuFeature). Clean exits skip the wait.
      let stderrTail = ''
      if (child.launch && (code !== 0 || signal)) {
        await child.launch.drained()
