    if (';&|(){}`'.includes(ch)) {
      endSegment()
      continue
    }
    if (ch === '$' && command[index + 1] === '(') {
      endSegment()
      index++
      continue
    }
    text += ch
    inToken = true
  }
  endSegment()
  return segments
}

/**
 * `C:\Program Files\Docker\docker.exe` → `docker`; `bin/rails` → `rails`;
 * `prisma@5` → `prisma`.
