function commandName(token: string): string {
  const base = token.split(/[\\/]/).pop() ?? token
  return base
    .toLowerCase()
    .replace(/(.)@[^@]*$/, '$1')
    .replace(/\.(exe|cmd|bat|com|ps1)$/, '')
