  if (refusedDatabaseScript(name, args)) {
    return { kind: 'database', invocation: `${runner} ${name}` }
  }
  if (refusedContainerScript(name)) {
    return { kind: 'container', invocation: `${runner} ${name}` }
  }
  return null
}

