  Object.entries({
    sudo: ['-u', '-g', '-h', '-p', '-c', '-r', '-t', '-d'],
    doas: ['-u', '-c'],
    env: ['-u', '-c', '--unset', '--chdir'],
    exec: ['-a'],
    command: [],
    builtin: [],
    nohup: [],
    time: ['-f', '-o', '--format', '--output'],
    nice: ['-n', '--adjustment'],
    timeout: ['-s', '-k', '--signal', '--kill-after'],
    xargs: ['-i', '-n', '-p', '-l', '-s', '-d', '-e', '-a'],
    watch: ['-n', '--interval'],
    stdbuf: ['-i', '-o', '-e'],
    caffeinate: ['-t', '-w'],
    unbuffer: [],
    'cross-env': [],
    'cross-env-shell': [],
    dotenv: ['-e', '-c', '-v', '-p'],
    'env-cmd': ['-f', '-e', '--file', '--environments'],
    call: [],
