+/** The arm vocabulary, in the precedence order the arm function applies. */
+export const FIRST_PARTY_MODEL_ARMS = [
+  'off',
+  'no_user',
+  'excluded',
+  'multi_placement',
+  'geo_ineligible',
+  'not_sampled',
+  'routed',
