+  return `fpm_${fnv1a(`${FIRST_PARTY_MODEL_ARM_SALT}:${userId ?? ''}`).toString(36)}`
+}
+
+/** 0..9999 in the shared first-party bucket space. Sticky per user. */
+export function firstPartyModelArmBucket(
+  userId: string | null | undefined,
+): number {
