// ------------------------------------------------------------------- lexing

/**
 * Split a command line into simple commands, respecting quotes.
 *
 * `;`, `&`, `|`, parentheses, braces, backticks, `$(` and newlines end a
 * command outside quotes; `&` inside a redirection (`2>&1`, `&>`) does not.
 */
function lexCommandLine(command: string): Token[][] {
  const segments: Token[][] = []
  let current: Token[] = []
  let text = ''
  let quoted = false
  let expands = false
  let inToken = false
  const endToken = () => {
    if (inToken) current.push({ text, quoted, literal: quoted && !expands })
    text = ''
    quoted = false
    expands = false
    inToken = false
  }
  const endSegment = () => {
    endToken()
    if (current.length > 0) segments.push(current)
    current = []
  }
  for (let index = 0; index < command.length; index++) {
    const ch = command[index]!
    if (ch === '"' || ch === "'") {
      const close = command.indexOf(ch, index + 1)
      text += command.slice(index + 1, close < 0 ? command.length : close)
      quoted = true
      if (ch === '"') expands = true
      inToken = true
      index = close < 0 ? command.length : close
      continue
    }
    if (ch === '\n' || ch === '\r') {
      endSegment()
      continue
    }
    if (/\s/.test(ch)) {
      endToken()
      continue
    }
    if (
      ch === '&' &&
      (command[index - 1] === '>' ||
        command[index - 1] === '<' ||
        command[index + 1] === '>')
    ) {
      text += ch
      inToken = true
      continue
    }
    if (';&|(){}`'.includes(ch)) {
      endSegment()
      continue
    }
    if (ch === '$' && command[index + 1] === '(') {
      endSegment()
      index++
      continue
    }
    text += ch
    inToken = true
  }
  endSegment()
  return segments
