+  if (!input) return input
+  const collapsed = input.includes('\r')
+    ? input
+        .replace(/\r+\n/g, '\n')
+        .split('\n')
+        .map((line) => line.slice(line.lastIndexOf('\r') + 1))
+        .join('\n')
+    : input
+  return sanitizeTerminalText(collapsed)
+}
+
