                  both things we did, not problems with this user's account. */}
              {belowPickerNotices.map((notice) => (
                <text
                  key={notice}
                  style={{ fg: theme.muted, wrapMode: 'word', marginTop: 1 }}
                >
                  {notice}
                </text>
              ))}
              {streakBonusNote && (
                <text
                  style={{ fg: theme.primary, wrapMode: 'word', marginTop: 1 }}
                >
                  {streakBonusNote}
                </text>
              )}
              {streakBonusStatus && (
