                    {formatAllowanceUsd(session.limit / 100)}
                  </span>{' '}
                  monthly usage. It resets in{' '}
                  <span fg={theme.foreground}>
                    {formatRetryAfter(session.retryAfterMs)}
                  </span>
                  . Press Ctrl+C to exit.
                </text>
              ) : (
                <text style={{ fg: theme.muted, wrapMode: 'word' }}>
