    nice: ['-n', '--adjustment'],
    timeout: ['-s', '-k', '--signal', '--kill-after'],
    xargs: ['-i', '-n', '-p', '-l', '-s', '-d', '-e', '-a'],
    watch: ['-n', '--interval'],
    stdbuf: ['-i', '-o', '-e'],
