  }
}
/** Every catalog handle in a catalog, by key, re-minted as `-h<n>`. */
export function rotateHandles(
  catalog: FreebuffModelCatalog,
  generation: number,
): FreebuffModelCatalog {
  return {
    ...catalog,
    rows: catalog.rows.map((row) => ({
      ...row,
      handle: `fbm1.${row.key}-h${generation}`,
    })),
  }
}
