    if (';&|(){}`'.includes(ch)) {
      endSegment()
      continue
    }
    if (ch === '$' && command[index + 1] === '(') {
      endSegment()
      index++
      continue
    }
    text += ch
    inToken = true
  }
  endSegment()
  return segments
}

/**
