        revision: connection.revision,
        patch: {
          model,
          ...(baseUrl ? { baseUrl } : {}),
          ...(parsedArgs.contextWindow !== undefined ? { contextWindow: parsedArgs.contextWindow } : {}),
          ...(parsedArgs.maxOutputTokens !== undefined ? { maxOutputTokens: parsedArgs.maxOutputTokens } : {}),
        },
      })
