    const body = JSON.stringify(args)

    const {
      responseHeaders,
      value: responseBody,
      rawValue: rawResponse,
    } = await postJsonToApi({
      url: this.config.url({
        path: '/chat/completions',
        modelId: this.modelId,
      }),
      headers: combineHeaders(this.config.headers(), options.headers),
      body: args,
      failedResponseHandler: this.failedResponseHandler,
      successfulResponseHandler: createJsonResponseHandler(
        OpenAICompatibleChatResponseSchema,
      ),
      abortSignal: options.abortSignal,
      fetch: this.config.fetch,
    })

    const choice = responseBody.choices[0]
    const content: Array<LanguageModelV2Content> = []

    // text content:
    const text = choice.message.content
    if (text != null && text.length > 0) {
      content.push({ type: 'text', text })
    }

    // reasoning content:
    const reasoning =
      choice.message.reasoning_content ?? choice.message.reasoning
    const reasoningDetails = choice.message.reasoning_details
    if (
      (reasoning != null && reasoning.length > 0) ||
      (reasoningDetails != null && reasoningDetails.length > 0)
    ) {
      content.push({
        type: 'reasoning',
        text: reasoning ?? '',
        ...(reasoningDetails != null && reasoningDetails.length > 0
          ? {
              providerMetadata: {
                [this.providerOptionsName]: {
                  reasoning_details: reasoningDetails,
                  model: this.modelId,
                },
              } as SharedV2ProviderMetadata,
            }
          : {}),
      })
    }

    // tool calls:
    if (choice.message.tool_calls != null) {
      for (const toolCall of choice.message.tool_calls) {
        content.push({
          type: 'tool-call',
          toolCallId: toolCall.id ?? generateId(),
          toolName: toolCall.function.name,
          input: toolCall.function.arguments!,
        })
      }
    }

    // provider metadata:
    const extractedMetadata =
      await this.config.metadataExtractor?.extractMetadata?.({
        parsedBody: rawResponse,
      })
    const providerMetadata: SharedV2ProviderMetadata = {
      [this.providerOptionsName]: {},
      ...extractedMetadata,
    }
    const completionTokenDetails = responseBody.usage?.completion_tokens_details
    if (completionTokenDetails?.accepted_prediction_tokens != null) {
      providerMetadata[this.providerOptionsName].acceptedPredictionTokens =
        completionTokenDetails?.accepted_prediction_tokens
    }
    if (completionTokenDetails?.rejected_prediction_tokens != null) {
      providerMetadata[this.providerOptionsName].rejectedPredictionTokens =
        completionTokenDetails?.rejected_prediction_tokens
    }

    return {
      content,
      finishReason: mapOpenAICompatibleFinishReason(choice.finish_reason),
      usage: {
        inputTokens: responseBody.usage?.prompt_tokens ?? undefined,
        outputTokens: responseBody.usage?.completion_tokens ?? undefined,
        totalTokens: responseBody.usage?.total_tokens ?? undefined,
        reasoningTokens:
          responseBody.usage?.completion_tokens_details?.reasoning_tokens ??
          undefined,
        cachedInputTokens:
          responseBody.usage?.prompt_tokens_details?.cached_tokens ?? undefined,
      },
      providerMetadata,
      request: { body },
      response: {
        ...getResponseMetadata(responseBody),
        headers: responseHeaders,
        body: rawResponse,
      },
      warnings,
    }
  }

  async doStream(
    options: Parameters<LanguageModelV2['doStream']>[0],
  ): Promise<Awaited<ReturnType<LanguageModelV2['doStream']>>> {
    const { args, warnings } = await this.getArgs({ ...options })

    const body = {
      ...args,
      stream: true,

      // only include stream_options when in strict compatibility mode:
      stream_options: this.config.includeUsage
        ? { include_usage: true }
        : undefined,
    }

    const metadataExtractor =
      this.config.metadataExtractor?.createStreamExtractor()

    const url = this.config.url({
      path: '/chat/completions',
      modelId: this.modelId,
    })
    const { responseHeaders, value: response } = await postJsonToApi({
      url,
      headers: combineHeaders(this.config.headers(), options.headers),
      body,
      failedResponseHandler: this.failedResponseHandler,
      successfulResponseHandler: createEventSourceResponseHandler(
        this.chunkSchema,
      ),
      abortSignal: options.abortSignal,
      fetch: this.config.fetch,
    })

    const toolCalls: Array<{
      id: string
      type: 'function'
      function: {
        name: string
        arguments: string
      }
      hasFinished: boolean
    }> = []

    let finishReason: LanguageModelV2FinishReason = 'unknown'
    const usage: {
      completionTokens: number | undefined
      completionTokensDetails: {
        reasoningTokens: number | undefined
        acceptedPredictionTokens: number | undefined
        rejectedPredictionTokens: number | undefined
      }
      promptTokens: number | undefined
      promptTokensDetails: {
        cachedTokens: number | undefined
      }
      totalTokens: number | undefined
    } = {
      completionTokens: undefined,
      completionTokensDetails: {
        reasoningTokens: undefined,
        acceptedPredictionTokens: undefined,
        rejectedPredictionTokens: undefined,
      },
      promptTokens: undefined,
      promptTokensDetails: {
        cachedTokens: undefined,
      },
      totalTokens: undefined,
    }
    let isFirstChunk = true
    const providerOptionsName = this.providerOptionsName
    const modelId = this.modelId
    let isActiveReasoning = false
    let isActiveText = false

    // Consolidated `reasoning_details` for the whole response: streamed
    // fragments merge by (type, id/index) — text concatenates, the signature
    // arrives on a fragment's final piece — so the assembled array can be
    // replayed verbatim on the next request's assistant message.
    const reasoningDetails: Array<Record<string, unknown>> = []
    const reasoningDetailByKey = new Map<string, Record<string, unknown>>()
    const addReasoningDetails = (details: unknown) => {
      if (!Array.isArray(details)) return
      for (const raw of details) {
        if (raw == null || typeof raw !== 'object') continue
        const detail = { ...(raw as Record<string, unknown>) }
        const key = `${detail.type ?? ''}:${detail.id ?? detail.index ?? 0}`
        const existing = reasoningDetailByKey.get(key)
        if (existing === undefined) {
          reasoningDetailByKey.set(key, detail)
          reasoningDetails.push(detail)
          continue
        }
        for (const field of ['text', 'data', 'summary'] as const) {
          if (typeof detail[field] === 'string') {
            existing[field] =
              typeof existing[field] === 'string'
                ? (existing[field] as string) + detail[field]
                : detail[field]
          }
        }
        for (const field of ['signature', 'format'] as const) {
          if (detail[field] != null) existing[field] = detail[field]
        }
      }
    }

    return {
      stream: response.pipeThrough(
        new TransformStream<
          ParseResult<z.infer<typeof this.chunkSchema>>,
          LanguageModelV2StreamPart
        >({
          start(controller) {
            controller.enqueue({ type: 'stream-start', warnings })
          },

          // TODO we lost type safety on Chunk, most likely due to the error schema. MUST FIX
          transform(chunk, controller) {
            // Emit raw chunk if requested (before anything else)
            if (options.includeRawChunks) {
              controller.enqueue({ type: 'raw', rawValue: chunk.rawValue })
            }

            // handle failed chunk parsing / validation:
            if (!chunk.success) {
              finishReason = 'error'
              controller.enqueue({ type: 'error', error: chunk.error })
              return
            }
            const value = chunk.value

            metadataExtractor?.processChunk(chunk.rawValue)

            // handle error chunks:
            if ('error' in value) {
              finishReason = 'error'
              controller.enqueue({
                type: 'error',
                error: streamErrorChunkToApiCallError({
                  errorValue: value.error,
                  url,
                  requestBodyValues: body,
                }),
              })
              return
            }

            if (isFirstChunk) {
              isFirstChunk = false

              controller.enqueue({
                type: 'response-metadata',
                ...getResponseMetadata(value),
              })
            }

            if (value.usage != null) {
              const {
                prompt_tokens,
                completion_tokens,
                total_tokens,
                prompt_tokens_details,
                completion_tokens_details,
              } = value.usage

              usage.promptTokens = prompt_tokens ?? undefined
              usage.completionTokens = completion_tokens ?? undefined
              usage.totalTokens = total_tokens ?? undefined
              if (completion_tokens_details?.reasoning_tokens != null) {
                usage.completionTokensDetails.reasoningTokens =
                  completion_tokens_details?.reasoning_tokens
              }
              if (
                completion_tokens_details?.accepted_prediction_tokens != null
              ) {
                usage.completionTokensDetails.acceptedPredictionTokens =
                  completion_tokens_details?.accepted_prediction_tokens
              }
              if (
                completion_tokens_details?.rejected_prediction_tokens != null
              ) {
                usage.completionTokensDetails.rejectedPredictionTokens =
                  completion_tokens_details?.rejected_prediction_tokens
              }
              if (prompt_tokens_details?.cached_tokens != null) {
                usage.promptTokensDetails.cachedTokens =
                  prompt_tokens_details?.cached_tokens
              }
            }

            const choice = value.choices[0]

            if (choice?.finish_reason != null) {
              finishReason = mapOpenAICompatibleFinishReason(
                choice.finish_reason,
              )
            }

            if (choice?.delta == null) {
              return
            }

            const delta = choice.delta

            if (delta.reasoning_details != null) {
              addReasoningDetails(delta.reasoning_details)
            }

            // enqueue reasoning before text deltas:
            const reasoningContent = delta.reasoning_content ?? delta.reasoning
            if (reasoningContent) {
              if (!isActiveReasoning) {
                controller.enqueue({
                  type: 'reasoning-start',
                  id: 'reasoning-0',
                })
                isActiveReasoning = true
              }

              controller.enqueue({
                type: 'reasoning-delta',
                id: 'reasoning-0',
                delta: reasoningContent,
              })
            }

            if (delta.content) {
              if (!isActiveText) {
                controller.enqueue({ type: 'text-start', id: 'txt-0' })
                isActiveText = true
              }

              controller.enqueue({
                type: 'text-delta',
                id: 'txt-0',
                delta: delta.content,
              })
            }

            if (delta.tool_calls != null) {
              for (const toolCallDelta of delta.tool_calls) {
                const index =
                  toolCallDelta.index ??
                  inferToolCallIndex(toolCalls, toolCallDelta)

                if (toolCalls[index] == null) {
                  if (toolCallDelta.function?.name == null) {
                    throw new InvalidResponseDataError({
                      data: toolCallDelta,
                      message: `Expected 'function.name' to be a string.`,
                    })
                  }

                  // UPDATED (James): Generate an ID if the provider doesn't include one (e.g., GLM models)
                  const toolCallId = toolCallDelta.id ?? generateId()

                  controller.enqueue({
                    type: 'tool-input-start',
                    id: toolCallId,
                    toolName: toolCallDelta.function.name,
                  })

                  toolCalls[index] = {
                    id: toolCallId,
                    type: 'function',
                    function: {
                      name: toolCallDelta.function.name,
                      arguments: toolCallDelta.function.arguments ?? '',
                    },
                    hasFinished: false,
                  }

                  const toolCall = toolCalls[index]

                  if (
                    toolCall.function?.name != null &&
                    toolCall.function?.arguments != null
                  ) {
                    // send delta if the argument text has already started:
                    if (toolCall.function.arguments.length > 0) {
                      controller.enqueue({
                        type: 'tool-input-delta',
                        id: toolCall.id,
                        delta: toolCall.function.arguments,
                      })
                    }

                    // check if tool call is complete
                    // (some providers send the full tool call in one chunk):
                    if (isParsableJson(toolCall.function.arguments)) {
                      controller.enqueue({
                        type: 'tool-input-end',
                        id: toolCall.id,
                      })

                      controller.enqueue({
                        type: 'tool-call',
                        toolCallId: toolCall.id ?? generateId(),
                        toolName: toolCall.function.name,
                        input: toolCall.function.arguments,
                      })
                      toolCall.hasFinished = true
                    }
                  }

                  continue
                }

                // existing tool call, merge if not finished
                const toolCall = toolCalls[index]

                if (toolCall.hasFinished) {
                  continue
                }

                if (toolCallDelta.function?.arguments != null) {
                  toolCall.function!.arguments +=
                    toolCallDelta.function?.arguments ?? ''
                }

                // send delta
                controller.enqueue({
                  type: 'tool-input-delta',
                  id: toolCall.id,
                  delta: toolCallDelta.function.arguments ?? '',
                })

                // check if tool call is complete
                if (
                  toolCall.function?.name != null &&
                  toolCall.function?.arguments != null &&
                  isParsableJson(toolCall.function.arguments)
                ) {
                  controller.enqueue({
                    type: 'tool-input-end',
                    id: toolCall.id,
                  })

                  controller.enqueue({
                    type: 'tool-call',
                    toolCallId: toolCall.id ?? generateId(),
                    toolName: toolCall.function.name,
                    input: toolCall.function.arguments,
                  })
                  toolCall.hasFinished = true
                }
              }
            }
          },

          flush(controller) {
            // Signature-only reasoning (e.g. fully redacted thinking) arrives
            // as details with no reasoning text; open the part so the details
            // still get a reasoning-end to ride on.
            if (!isActiveReasoning && reasoningDetails.length > 0) {
              controller.enqueue({ type: 'reasoning-start', id: 'reasoning-0' })
              isActiveReasoning = true
            }
            if (isActiveReasoning) {
              controller.enqueue({
                type: 'reasoning-end',
                id: 'reasoning-0',
                ...(reasoningDetails.length > 0
                  ? {
                      providerMetadata: {
                        [providerOptionsName]: {
                          reasoning_details: reasoningDetails,
                          model: modelId,
                        },
                      } as SharedV2ProviderMetadata,
                    }
                  : {}),
              })
            }

            if (isActiveText) {
              controller.enqueue({ type: 'text-end', id: 'txt-0' })
            }

            // go through all tool calls and send the ones that are not finished
            for (const toolCall of toolCalls.filter(
              (toolCall) => !toolCall.hasFinished,
            )) {
              controller.enqueue({
                type: 'tool-input-end',
                id: toolCall.id,
              })

              controller.enqueue({
                type: 'tool-call',
                toolCallId: toolCall.id ?? generateId(),
                toolName: toolCall.function.name,
                input: toolCall.function.arguments,
              })
            }

            const providerMetadata: SharedV2ProviderMetadata = {
              [providerOptionsName]: {},
              ...metadataExtractor?.buildMetadata(),
            }
            if (
              usage.completionTokensDetails.acceptedPredictionTokens != null
            ) {
              providerMetadata[providerOptionsName].acceptedPredictionTokens =
                usage.completionTokensDetails.acceptedPredictionTokens
            }
            if (
              usage.completionTokensDetails.rejectedPredictionTokens != null
            ) {
              providerMetadata[providerOptionsName].rejectedPredictionTokens =
                usage.completionTokensDetails.rejectedPredictionTokens
            }

            controller.enqueue({
              type: 'finish',
              finishReason,
              usage: {
                inputTokens: usage.promptTokens ?? undefined,
                outputTokens: usage.completionTokens ?? undefined,
                totalTokens: usage.totalTokens ?? undefined,
                reasoningTokens:
                  usage.completionTokensDetails.reasoningTokens ?? undefined,
                cachedInputTokens:
                  usage.promptTokensDetails.cachedTokens ?? undefined,
              },
              providerMetadata,
            })
          },
        }),
      ),
      request: { body },
      response: { headers: responseHeaders },
    }
  }
}

/**
 * The slot of a streamed tool-call delta that carries no `index`. OpenAI
 * always sends one, but several OpenAI-compatible servers and proxies do not
 * (seen with local routers in front of other providers), and a chunk that
 * failed the schema dropped the call: the turn ended with "Writing the
 * file." and no write. Without an index:
 * - an `id` names its call: an existing one continues, a new one opens a slot;
 * - a delta with no `id` continues the call still being streamed, unless it
 *   names a different function (then it is a new call);
 * - anything else opens a new slot.
 */
export function inferToolCallIndex(
  toolCalls: ReadonlyArray<
    | { id: string; function: { name: string }; hasFinished: boolean }
    | undefined
  >,
  delta: { id?: string | null; function: { name?: string | null } },
): number {
  if (delta.id != null) {
    const existing = toolCalls.findIndex((call) => call?.id === delta.id)
    return existing === -1 ? toolCalls.length : existing
  }
  const lastIndex = toolCalls.length - 1
  const last = toolCalls[lastIndex]
  if (
    last &&
    !last.hasFinished &&
    (delta.function.name == null || delta.function.name === last.function.name)
  )
    return lastIndex
  return delta.function.name == null && last ? lastIndex : toolCalls.length
}

