          key.preventDefault?.()
          if (focusedIndex === 0) {
            void handleTakeover()
          } else {
            void (onBack ? onBack() : exitCliCleanly())
          }
          return
        }

        if (isRight || isTab) {
          key.preventDefault?.()
          setFocusedIndex((prev) => (prev + 1) % 2)
          return
        }

        if (isLeft || isShiftTab) {
          key.preventDefault?.()
          setFocusedIndex((prev) => (prev - 1 + 2) % 2)
          return
        }
      },
      [focusedIndex, handleTakeover, onBack],
    ),
