            <box
              style={{
                flexDirection: 'column',
                alignItems: 'flex-start',
                gap: 0,
              }}
            >
              {freebucksIntro.visible && (
                <FreebucksIntroCard
                  width={Math.min(contentMaxWidth, 72)}
                  onDismiss={freebucksIntro.dismiss}
                />
