-export function sanitizeVerificationText(text: string): string {
-  return text
-    .replace(SECRET_LIKE, '[redacted]')
-    .replace(
-      /\b(?:sk|rk|tok|key|secret)_[A-Za-z0-9_-]{8,}\b/g,
-      '[redacted]',
-    )
-    .replace(/\b[A-Za-z0-9+/]{32,}={0,2}\b/g, '[redacted]')
-    .slice(0, 280)
-}
