-function globToRegExp(pattern: string): RegExp {
-  const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&')
-  return new RegExp(
-    `^${escaped.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*')}$`,
-  )
-}
